// The main thread's side of the generated-UI worker: one module worker per
// page, created on the first send, evaluating one revision at a time.
import { decodeTree } from './decode.js';

let worker: Worker | null = null;
const waiting = new Map<number, { resolve: (value: any) => void; reject: (error: Error) => void }>();

function getWorker() {
	if (!worker) {
		worker = new Worker(new URL('./worker.js', import.meta.url), { type: 'module', name: 'genui' });
		worker.onmessage = ({ data }) => {
			const entry = waiting.get(data.seq);
			if (!entry)
				return;
			waiting.delete(data.seq);
			if (data.type === 'error')
				entry.reject(new Error(data.message));
			else
				entry.resolve(decodeTree(data.buffer));
		};
	}
	return worker;
}

export function evaluateInWorker(revision: any): Promise<{ seq: number; tree: any }> {
	const promise = new Promise<{ seq: number; tree: any }>((resolve, reject) => {
		waiting.set(revision.seq, { resolve, reject });
		getWorker().postMessage({ type: 'revision', revision });
	});
	return promise;
}

export function resetWorker() {
	worker?.postMessage({ type: 'reset' });
}
