// Word bookkeeping for streamed replies. Text in a decoded tree is counted
// in document order; words past the previous revision's count are new and
// render as streaming-word spans.
// A word with the whitespace after it; the first word of a text run keeps
// the whitespace before it too.
const WORD = /^\s*\S+\s*|\S+\s*/g;

export function countWords(tree: any): number {
	let count = 0;
	const visit = (node: any) => {
		if (typeof node === 'string') {
			count += node.match(WORD)?.length ?? 0;
			return;
		}
		if (node.type === 'widget')
			return;
		for (const child of node.children)
			visit(child);
	};
	if (tree)
		visit(tree);
	return count;
}

export function splitWords(text: string): string[] {
	return text.match(WORD) ?? (text ? [text] : []);
}

export type TextNode = { type: '#text'; text: string; start: number; count: number };

// Turns the strings of a decoded tree into text nodes that carry their first
// word's index, and reuses the previous revision's node objects wherever a
// subtree is unchanged, so memoized components bail out on them.
export function prepareTree(previous: any, tree: any) {
	let index = 0;
	const annotate = (node: any): any => {
		if (typeof node === 'string') {
			const count = node.match(WORD)?.length ?? 0;
			const text: TextNode = { type: '#text', text: node, start: index, count };
			index += count;
			return text;
		}
		if (node.type === 'widget')
			return node;
		return { type: node.type, props: node.props, children: node.children.map(annotate) };
	};
	return share(previous, annotate(tree));
}

function sameProps(a: any, b: any) {
	const keys = Object.keys(a);
	if (keys.length !== Object.keys(b).length)
		return false;
	for (const key of keys) {
		const x = a[key];
		const y = b[key];
		if (x !== y && JSON.stringify(x) !== JSON.stringify(y))
			return false;
	}
	return true;
}

function share(previous: any, next: any): any {
	if (!previous || previous.type !== next.type)
		return next;
	if (next.type === '#text')
		return previous.text === next.text && previous.start === next.start ? previous : next;
	if (!sameProps(previous.props, next.props))
		return next;
	const children = next.children.map((child: any, i: number) => share(previous.children?.[i], child));
	if (children.length === previous.children.length && children.every((child: any, i: number) => child === previous.children[i]))
		return previous;
	return { ...next, children };
}
