import { BINARY, NODE_TYPES } from "./format.js";

const decoder = new TextDecoder();

export const readUint32 = (r) => {
    const v = r.view.getUint32(r.offset, true);
    r.offset += 4;
    return v;
};

export const readUint8 = (r) => r.view.getUint8(r.offset++);

export const readFloat64 = (r) => {
    const v = r.view.getFloat64(r.offset, true);
    r.offset += 8;
    return v;
};

export const readString = (r) => {
    const length = readUint32(r);
    const s = decoder.decode(new Uint8Array(r.view.buffer, r.view.byteOffset + r.offset, length));
    r.offset += length;
    return s;
};

export const readValue = (r) => {
    switch (readUint8(r)) {
        case BINARY.VALUE_NULL:
            return null;
        case BINARY.VALUE_FALSE:
            return false;
        case BINARY.VALUE_TRUE:
            return true;
        case BINARY.VALUE_UINT32:
            return readUint32(r);
        case BINARY.VALUE_FLOAT64:
            return readFloat64(r);
        case BINARY.VALUE_STRING:
            return r.strings[readUint32(r)];
        case BINARY.VALUE_ARRAY: {
            const length = readUint32(r);
            const out = new Array(length);
            for (let i = 0; i < length; i++) {
                out[i] = readValue(r);
            }
            return out;
        }
        case BINARY.VALUE_OBJECT: {
            const length = readUint32(r);
            const out = {};
            for (let i = 0; i < length; i++) {
                const key = r.strings[readUint32(r)];
                out[key] = readValue(r);
            }
            return out;
        }
        default:
            throw new Error("bad value tag");
    }
};

const readNode = (r) => {
    const kind = readUint8(r);
    if (kind === BINARY.NODE_TEXT) {
        return r.strings[readUint32(r)];
    }
    if (kind !== BINARY.NODE_ELEMENT) {
        throw new Error("bad node kind");
    }
    const type = NODE_TYPES[readUint8(r)];
    const count = readUint32(r);
    const props = readValue(r);
    const children = new Array(count);
    for (let i = 0; i < count; i++) {
        children[i] = readNode(r);
    }
    return { type, props, children };
};

/** Decodes a buffer produced by encodeTree into { seq, tree }. */
export const decodeTree = (buffer) => {
    const view = new DataView(buffer);
    const r = { view, offset: 0, strings: [] };
    if (readUint32(r) !== BINARY.MAGIC) {
        throw new Error("bad magic");
    }
    if (readUint32(r) !== BINARY.VERSION) {
        throw new Error("unsupported version");
    }
    const seq = readUint32(r);
    readUint32(r);
    const tableOffset = readUint32(r);
    r.offset = tableOffset;
    const count = readUint32(r);
    r.strings = new Array(count);
    for (let i = 0; i < count; i++) {
        r.strings[i] = readString(r);
    }
    r.offset = BINARY.HEADER_BYTES;
    return { seq, tree: readNode(r) };
};
